/** 12 patroonregels; volgorde is significant. */
const PATTERNS = [
  { re: /^\/(.*\/)?feed(\.html)?(\/atom)?\/?$/, to: "/rss.xml", status: 301 },
  { re: /^\/comments\/feed(\.html)?\/?$/, to: "/rss.xml", status: 301 },
  { re: /^(\/(?:es|fr|pt|ru)?\/?\d{4}\/\d{2}\/[^/]+\/)comment-page-\d+\/?$/, to: "$1", status: 301 },
  { re: /^(?:\/(?:es|fr|pt|ru))?\/tag\/([^/]+)\/page\/\d+\/?$/, to: "/tag/$1/", status: 301 },
  { re: /^(?:\/(?:es|fr|pt|ru))?\/author\/([^/]+)\/page\/\d+\/?$/, to: "/author/$1/", status: 301 },
  { re: /^(?:\/(?:es|fr|pt|ru))?\/author\/[^/]+\/[^/]+\/?$/, to: null, status: 410 },
  { re: /^\/(?:es|fr|pt|ru)\/\d{4}\/\d{2}\/[^/]+\.html$/, to: null, status: 410 },
  { re: /^\/wp-content\/uploads\/(?:.*\/)?([^/]+\.(?:pdf|pptx?|docx?|zip))$/, to: "/downloads/$1", status: 301 },
  { re: /^\/wp-content\/uploads\/(.+)$/, to: "/media/$1", status: 301 },
  { re: /^\/wp-(admin|json|includes|login|content)(\.html|[/.].*)?$/, to: null, status: 410 },
  { re: /^\/user\/.*$/, to: null, status: 410 },
  { re: /^\/(?:es|fr|pt|ru)\/(.*)$/, to: "/$1", status: 301 },
];

function redirect(to, status) {
  return status === 410
    ? new Response(null, { status: 410 })
    : new Response(null, { status, headers: { Location: to, "Cache-Control": "max-age=3600" } });
}

function resolve(path) {
  const hit = EXACT[path];
  if (hit) return redirect(hit[0], hit[1]);
  for (const p of PATTERNS) {
    const m = path.match(p.re);
    if (!m) continue;
    const to = p.to ? p.to.replace(/\$(\d)/g, (_, n) => m[Number(n)] ?? "") : null;
    return redirect(to, p.status);
  }
  return null;
}

servePullZone({ url: "https://tastycupcakes.org" }).onOriginRequest((ctx) => {
  const response = resolve(new URL(ctx.request.url).pathname);
  return Promise.resolve(response ?? ctx.request);
});
